const RAIL_LABEL = {
  requests: "Заявки",
  manage: "Управ­ление",
  tools: "Инстру­менты",
  service: "Сервис",
};

const resolveActive = (id) => {
  for (const cat of CATEGORIES) {
    for (const it of cat.items) {
      if (it.ids.includes(id)) return { catKey: cat.key, to: it.to };
    }
  }
  // Эскадрилья — дефолт для пустого/неизвестного id
  return { catKey: "requests", to: "/relay?page=1" };
};

const SuperAdminMenu = ({
  id,
  allCreatedRequests,
  fapCreatedCount = 0,
  transferPendingCount = 0,
  activeSupportCount,
  menuOpen,
  setMenuOpen,
}) => {
  const active = resolveActive(id);
  const [railCat, setRailCat] = useState(active.catKey);
  const [query, setQuery] = useState("");

  // Синхронизируем активную категорию рельса при смене страницы
  useEffect(() => {
    setRailCat(active.catKey);
  }, [active.catKey]);

  // Сбрасываем поиск при переключении категории
  useEffect(() => {
    setQuery("");
  }, [railCat]);

  const badges = {
    requests: allCreatedRequests,
    fapCreated: fapCreatedCount,
    transferPending: transferPendingCount,
    support: activeSupportCount,
  };

  const currentCat = CATEGORIES.find((c) => c.key === railCat) || CATEGORIES[0];
  const q = query.trim().toLowerCase();
  const shownItems = q
    ? currentCat.items.filter((it) => it.label.toLowerCase().includes(q))
    : currentCat.items;

  const handleRailClick = (key) => {
    setRailCat(key);
    if (!menuOpen) setMenuOpen(true);
  };

  return (
    <div className={classes.root}>
      {/* ===== РЕЛЬС ===== */}
      <div className={classes.rail}>
        <Link to={"/"} className={classes.railLogo}>
          <img src="/kars_avia_logo_05.png" alt="Карс Авиа" />
        </Link>

        {CATEGORIES.map((cat) => (
          <button
            key={cat.key}
            type="button"
            onClick={() => handleRailClick(cat.key)}
            className={`${classes.railBtn} ${railCat === cat.key ? classes.railBtnActive : ""}`}
            title={cat.title}
          >
            {RailIcon[cat.key]}
            <span className={classes.railBtnLabel}>{RAIL_LABEL[cat.key]}</span>
          </button>
        ))}

        <div className={classes.railBottom}>
          <button
            type="button"
            className={classes.railIconBtn}
            onClick={() => setMenuOpen(!menuOpen)}
            title={menuOpen ? "Свернуть" : "Развернуть"}
          >
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <path d={menuOpen ? "M15 6l-6 6 6 6" : "M9 6l6 6-6 6"} />
            </svg>
          </button>
          <Link to={"/documentation"} className={classes.railIconBtn} title="Помощь">
            {ItemIcon.help}
          </Link>
        </div>
      </div>

      {/* ===== ПАНЕЛЬ ===== */}
      {menuOpen && (
        <div className={classes.panel}>
          <div className={classes.panelHead}>
            <span className={classes.panelTitle}>{currentCat.title}</span>
            <span className={classes.panelCount}>{currentCat.items.length}</span>
          </div>
          <div className={classes.panelSub}>Выберите раздел</div>

          <div className={classes.search}>
            <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="#7f808a" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <circle cx="11" cy="11" r="7" />
              <line x1="21" y1="21" x2="16.65" y2="16.65" />
            </svg>
            <input
              className={classes.searchInput}
              type="text"
              placeholder="Поиск в разделе"
              value={query}
              onChange={(e) => setQuery(e.target.value)}
            />
          </div>

          <div className={classes.list}>
            {shownItems.map((it) => {
              const isActive = it.to === active.to;
              const count = it.badgeKey ? badges[it.badgeKey] : 0;
              return (
                <Link
                  key={it.to}
                  to={it.to}
                  className={`${classes.item} ${isActive ? classes.itemActive : ""}`}
                >
                  <span className={classes.itemIcon}>{it.icon}</span>
                  <span className={classes.itemBody}>
                    <span className={classes.itemLabel}>{it.label}</span>
                    <span className={classes.itemMeta}>{it.meta}</span>
                  </span>
                  {count > 0 && <span className={classes.itemBadge}>{count}</span>}
                </Link>
              );
            })}
            {shownItems.length === 0 && (
              <div className={classes.empty}>Ничего не найдено</div>
            )}
          </div>

          <div className={classes.footer}>
            <Link to={"/patchNotes"} className={classes.footerVer}>
              ver 4.4.0
            </Link>
            <span className={classes.footerPow}>
              Powered by <a>Alazar studio</a>
            </span>
          </div>
        </div>
      )}
    </div>
  );
};

export default SuperAdminMenu;
